declare(strict_types=1);require_once __DIR__.'/product.php';require_once __DIR__.'/migration-runner.php';
function inst_e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fld(string $l,string $n,string $v='',string $t='text',bool $required=true):string{return'<label class="field"><span>'.inst_e($l).'</span><input name="'.inst_e($n).'" value="'.inst_e($v).'" type="'.inst_e($t).'"'.($required?' required':'').'></label>';}
function env_read_simple(string $p):array{$o=[];if(!is_file($p))return$o;foreach(file($p,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[]as$l){$l=trim($l);if($l===''||$l[0]==='#'||!str_contains($l,'='))continue;[$k,$v]=explode('=',$l,2);$o[trim($k)]=trim(trim($v),"\"'");}return$o;}function env_write(string $p,array$d):void{$a=[];foreach($d as$k=>$v){$v=(string)$v;if(preg_match('/[\s#=]/',$v))$v='"'.str_replace(['\\','"'],['\\\\','\\"'],$v).'"';$a[]=$k.'='.$v;}if(file_put_contents($p,implode(PHP_EOL,$a).PHP_EOL,LOCK_EX)===false)throw new RuntimeException('Cannot write .env');}
function requirements():array{$s=__DIR__.'/storage';return[['PHP 8.2+',version_compare(PHP_VERSION,'8.2.0','>=')],['PDO MySQL',extension_loaded('pdo_mysql')],['OpenSSL',extension_loaded('openssl')],['Fileinfo',extension_loaded('fileinfo')],['ZIP',extension_loaded('zip')],['GD',extension_loaded('gd')],['mbstring',extension_loaded('mbstring')],['storage writable',(is_dir($s)||@mkdir($s,0770,true))&&is_writable($s)],['application folder writable',is_writable(__DIR__)]];}
$env=env_read_simple(__DIR__.'/.env');$mode=(string)($env['APP_MODE']??(is_file(__DIR__.'/package-mode.php')?(require __DIR__.'/package-mode.php'):'hosted'));$offline=$mode==='offline';$req=requirements();$reqOk=!in_array(false,array_column($req,1),true);$step=(string)($_GET['step']??($offline?'company':'requirements'));$error='';$success=false;$installed=false;
if($env&&!empty($env['DB_DATABASE'])){try{$pdo=new PDO('mysql:host='.($env['DB_HOST']??'127.0.0.1').';port='.(int)($env['DB_PORT']??3306).';dbname='.$env['DB_DATABASE'].';charset=utf8mb4',$env['DB_USERNAME']??'root',$env['DB_PASSWORD']??'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$hasUsers=(bool)$pdo->query("SHOW TABLES LIKE 'users'")->fetchColumn();$installed=$hasUsers&&(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()>0;}catch(Throwable $e){}}
if($installed){require __DIR__.'/bootstrap.php';$u=current_user();if(!$u){header('Location:login.php');exit;}$success=true;}
if(!$installed&&($_SERVER['REQUEST_METHOD']??'GET')==='POST'){$host=$offline?($env['DB_HOST']??'127.0.0.1'):trim((string)($_POST['db_host']??'127.0.0.1'));$port=$offline?(int)($env['DB_PORT']??3307):(int)($_POST['db_port']??3306);$name=$offline?($env['DB_DATABASE']??'crm_workspace'):trim((string)($_POST['db_name']??'crm_workspace'));$dbUser=$offline?($env['DB_USERNAME']??'crmapp'):trim((string)($_POST['db_user']??'root'));$dbPass=$offline?($env['DB_PASSWORD']??''):(string)($_POST['db_pass']??'');$company=trim((string)($_POST['company_name']??''));$slug=trim((string)($_POST['company_slug']??'company'));$adminName=trim((string)($_POST['admin_name']??''));$adminEmail=trim((string)($_POST['admin_email']??''));$adminPass=(string)($_POST['admin_pass']??'');try{if(!$reqOk)throw new RuntimeException('Server requirements are not satisfied.');if(!$company||!preg_match('/^[a-z0-9-]+$/',$slug)||!$adminName||!filter_var($adminEmail,FILTER_VALIDATE_EMAIL)||strlen($adminPass)<10)throw new RuntimeException('Complete all fields; password must contain at least 10 characters.');$root=new PDO("mysql:host=$host;port=$port;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);if(!preg_match('/^[A-Za-z0-9_]+$/',$name))throw new RuntimeException('Invalid database name.');$root->exec("CREATE DATABASE IF NOT EXISTS `$name` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$pdo=new PDO("mysql:host=$host;port=$port;dbname=$name;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);migration_run($pdo,true);$pdo->beginTransaction();$pdo->prepare('INSERT INTO companies(name,slug,primary_color,accent_color) VALUES(?,?,?,?)')->execute([$company,$slug,'#173f35','#bd9856']);$cid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO users(company_id,name,email,password_hash,role,title,lang,active) VALUES(?,?,?,?,?,?,?,1)')->execute([$cid,$adminName,$adminEmail,password_hash($adminPass,defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT),'supe