?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=inst_e(APP_PRODUCT_NAME)?> Installer</title><link rel="stylesheet" href="assets/app.css?v=<?=APP_VERSION?>"><style>.install{max-width:900px;margin:35px auto}.req{display:flex;justify-content:space-between;padding:9px;border-bottom:1px solid #ddd}.pass{color:#176846}.fail{color:#a73333}</style></head><body><main class="panel install"><h1><?=inst_e(APP_PRODUCT_NAME)?> · <?=inst_e($mode)?></h1><?php if($success):?><div class="state success"><h2>نصب کامل شد / Installation complete</h2><a class="btn primary" href="login.php">ورود / Sign in</a></div><?php elseif($step==='requirements'):?><h2>بررسی نیازمندی‌ها / Requirements</h2><?php foreach($req as[$label,$ok]):?><div class="req"><span><?=inst_e($label)?></span><b class="<?=$ok?'pass':'fail'?>"><?=$ok?'PASS ✓':'FAIL ✕'?></b></div><?php endforeach?><p>همه موارد باید PASS باشند. / All checks must pass before database setup.</p><?php if($reqOk):?><a class="btn primary" href="install.php?step=company">ادامه / Continue</a><?php endif?><?php else:?><?php if($error):?><div class="alert danger"><?=inst_e($error)?></div><?php endif?><form method="post" class="form-grid"><?php if(!$offline):?><h3 class="full">Database</h3><?=fld('Host','db_host','127.0.0.1')?><?=fld('Port','db_port','3306','number')?><?=fld('Database','db_name','crm_workspace')?><?=fld('User','db_user','root')?><?=fld('Password','db_pass','','password',false)?><?php else:?><div class="full offline-banner">Database was configured automatically by the Windows installer.</div><?php endif?><h3 class="full">شرکت / Company</h3><?=fld('Company name','company_name','My Company')?><?=fld('Company code','company_slug','company')?><?=fld('Administrator name','admin_name','Administrator')?><?=fld('Administrator email','admin_email','','email')?><?=fld('Password (10+ characters)','admin_pass','','password')?><button class="btn prim